#!/usr/bin/env python3
import argparse,hashlib,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--out',type=Path,required=True);a=p.parse_args();root=Path(__file__).resolve().parents[1];sdk=root/'.cache/emsdk/upstream/emscripten';out=a.out.resolve();assert not out.exists();out.mkdir(parents=True)
source=root/'scripts/standalone-sdk-directory-probe.c';cmd=[str(sdk/'emcc'),'-O2','-g','-sMEMORY64=1','-sFORCE_FILESYSTEM=1','-sMODULARIZE=1','-sEXPORT_ES6=1','-sENVIRONMENT=node','-sALLOW_MEMORY_GROWTH=1','-sEXPORTED_RUNTIME_METHODS=HEAPU8,FS,UTF8ToString','--no-entry','-I'+str(sdk/'system/lib/libc/musl/src/dirent'),'-sEXPORTED_FUNCTIONS='+json.dumps(['_'+n for n in ['opendir','readdir','closedir','dirfd','rewinddir','sdk_dir_errno','sdk_dir_layout','malloc','free','close']]),str(source),'-o',str(out/'reference.mjs')];r=subprocess.run(cmd,capture_output=True,text=True);(out/'build.log').write_text(r.stdout+r.stderr);assert r.returncode==0,r.stderr
inputs=[Path(__file__).resolve(),source,sdk/'src/lib/libsyscall.js',sdk/'src/lib/libfs.js',sdk/'src/lib/libmemfs.js',sdk/'cache/sysroot/include/bits/dirent.h',sdk/'cache/sysroot/include/dirent.h'];inputs.extend((sdk/'system/lib/libc/musl/src/dirent').glob('*.[ch]'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();(out/'receipt.json').write_text(json.dumps({'profile':'Actual pinned SDK MEMFS MEMORY64 O2 musl directory leaves, no replaced bodies','sourceSha256':{str(p):sha(p)for p in inputs},'artifactSha256':{p.name:sha(p)for p in [out/'reference.mjs',out/'reference.wasm']}},indent=2)+'\n');print(out)
